export type BookingRecord = { id: number; seats: number };

export type BookingState =
  | { step: 'draft' }
  | { step: 'invalid'; code: string }
  | { step: 'pending'; record: BookingRecord }
  | { step: 'confirmed'; record: BookingRecord }
  | { step: 'cancelled'; record: BookingRecord; reason: string };
export type Step = BookingState['step'];
export type ActiveState = { step: 'pending'; record: BookingRecord } | { step: 'confirmed'; record: BookingRecord };

function assertNever(x: never): never {
  throw new Error('Unhandled booking state: ' + JSON.stringify(x));
}

export function describe(state: BookingState): string {
  switch (state.step) {
    case 'draft': return 'Draft';
    case 'invalid': return 'Invalid: ' + state.code;
    case 'pending': return 'Pending #' + state.record.id;
    case 'confirmed': return 'Confirmed #' + state.record.id;
    case 'cancelled': return 'Cancelled #' + state.record.id + ': ' + state.reason;
    default: return assertNever(state);
  }
}

export function isActive(state: BookingState): state is ActiveState {
  return state.step === 'pending' || state.step === 'confirmed';
}

export const STEP_LABEL: Record<Step, string> = {
  draft: 'Draft', invalid: 'Invalid', pending: 'Pending', confirmed: 'Confirmed', cancelled: 'Cancelled',
};

import { describe, isActive, STEP_LABEL } from '../src/state.ts';
import type { BookingState, ActiveState } from '../src/state.ts';

declare const rec: { id: number; seats: number };
const states: BookingState[] = [
  { step: 'draft' },
  { step: 'pending', record: rec },
  { step: 'confirmed', record: rec },
  { step: 'cancelled', record: rec, reason: 'x' },
];
for (const s of states) { void describe(s); void STEP_LABEL[s.step]; }

declare const some: BookingState;
if (isActive(some)) { const a: ActiveState = some; void a.record.id; }

import { describe } from '../src/state.ts';
import type { BookingState } from '../src/state.ts';

declare const rec: { id: number; seats: number };
declare const s: BookingState;
describe({ step: 'pending' }); // expect TS2345
if (s.step === 'draft') { const id = s.record.id; void id; } // expect TS2339
if (s.step === 'xpired') { void 0; } // expect TS2367

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { describe, isActive } from '../src/state.ts';
import type { BookingState } from '../src/state.ts';

const rec = { id: 7, seats: 30 };
test('describe', () => {
  assert.equal(describe({ step: 'draft' }), 'Draft');
  assert.equal(describe({ step: 'cancelled', record: rec, reason: 'exam' }), 'Cancelled #7: exam');
});
test('isActive', () => {
  assert.equal(isActive({ step: 'confirmed', record: rec }), true);
  assert.equal(isActive({ step: 'draft' }), false);
});

